import type { OmniRouteConfig, OmniRouteModel, OmniRouteModelMetadata, OmniRouteModelsResponse } from './types.js';
import {
  OMNIROUTE_DEFAULT_MODELS,
  OMNIROUTE_ENDPOINTS,
  MODEL_CACHE_TTL,
  REQUEST_TIMEOUT,
} from './constants.js';
import { getModelsDevIndex, normalizeModelKey } from './models-dev.js';
import type { ModelsDevIndex } from './models-dev.js';
import { enrichComboModels, clearComboCache } from './omniroute-combos.js';

/**
 * Model cache entry
 */
interface ModelCache {
  models: OmniRouteModel[];
  timestamp: number;
}

/**
 * In-memory model cache keyed by endpoint and API key
 */
const modelCache = new Map<string, ModelCache>();

/**
 * Generate a cache key for a given configuration
 */
function getCacheKey(config: OmniRouteConfig, apiKey: string): string {
  const baseUrl = config.baseUrl || OMNIROUTE_ENDPOINTS.BASE_URL;
  return `${baseUrl}:${apiKey}`;
}

/**
 * Fetch models from OmniRoute /v1/models endpoint
 * This is the CRITICAL FEATURE - dynamically fetches available models
 *
 * @param config - OmniRoute configuration
 * @param apiKey - API key for authentication
 * @returns Array of available models
 */
export async function fetchModels(
  config: OmniRouteConfig,
  apiKey: string,
  forceRefresh: boolean = false,
): Promise<OmniRouteModel[]> {
  const cacheKey = getCacheKey(config, apiKey);

  // Check cache first if not forcing refresh
  if (!forceRefresh) {
    // Validate TTL is positive to prevent unexpected cache behavior
    const cacheTtl =
      config.modelCacheTtl && config.modelCacheTtl > 0 ? config.modelCacheTtl : MODEL_CACHE_TTL;

    const cached = modelCache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp < cacheTtl) {
      console.log('[OmniRoute] Using cached models');
      return cached.models;
    }
  } else {
    console.log('[OmniRoute] Forcing model refresh');
  }

  // Use default baseUrl if not provided to prevent undefined URL
  const baseUrl = config.baseUrl || OMNIROUTE_ENDPOINTS.BASE_URL;
  const modelsUrl = `${baseUrl}${OMNIROUTE_ENDPOINTS.MODELS}`;

  console.log(`[OmniRoute] Fetching models from ${modelsUrl}`);

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT);

  try {
    const response = await fetch(modelsUrl, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      signal: controller.signal,
    });

    if (!response.ok) {
      // Sanitize error - only log status, not response body
      console.error(
        `[OmniRoute] Failed to fetch models: ${response.status} ${response.statusText}`,
      );
      throw new Error(`Failed to fetch models: ${response.status} ${response.statusText}`);
    }

    // Parse and validate response structure before type casting
    const rawData = await response.json();

    // Runtime validation to ensure API returns expected structure
    if (!rawData || typeof rawData !== 'object' || !Array.isArray(rawData.data)) {
      console.error('[OmniRoute] Invalid models response structure:', rawData);
      throw new Error('Invalid models response structure: expected { data: Array }');
    }

    const data = rawData as OmniRouteModelsResponse;

    // Transform and validate models - filter out invalid entries
    const rawModels = data.data
      .filter(
        (model): model is OmniRouteModel =>
          model !== null && model !== undefined && typeof model.id === 'string',
      )
      .map((model) => ({
        ...model,
        // Ensure required fields
        id: model.id,
        name: model.name || model.id,
        description: model.description || `OmniRoute model: ${model.id}`,
        // Keep undefined for enrichment to work properly
        contextWindow: model.contextWindow,
        maxTokens: model.maxTokens,
        supportsStreaming: model.supportsStreaming,
        supportsVision: model.supportsVision,
        supportsTools: model.supportsTools,
      }));

    // Enrich with models.dev and combo capabilities
    const models = await enrichModelMetadata(rawModels, config);

    // Update cache
    modelCache.set(cacheKey, {
      models,
      timestamp: Date.now(),
    });

    console.log(`[OmniRoute] Successfully fetched ${models.length} models`);
    return models;
  } catch (error) {
    console.error('[OmniRoute] Error fetching models:', error);

    // Return cached models if available (even if expired)
    const cached = modelCache.get(cacheKey);
    if (cached) {
      console.log('[OmniRoute] Returning expired cached models as fallback');
      return cached.models;
    }

    // Return default models as last resort
    console.log('[OmniRoute] Returning default models as fallback');
    return config.defaultModels || OMNIROUTE_DEFAULT_MODELS;
  } finally {
    // Always clear the timeout to prevent memory leaks
    clearTimeout(timeoutId);
  }
}

/**
 * Clear the model cache
 * @param config - Optional OmniRoute configuration to clear specific cache
 * @param apiKey - Optional API key to clear specific cache
 */
export function clearModelCache(config?: OmniRouteConfig, apiKey?: string): void {
  if (config && apiKey) {
    const cacheKey = getCacheKey(config, apiKey);
    modelCache.delete(cacheKey);
    console.log('[OmniRoute] Model cache cleared for provided configuration');
  } else {
    modelCache.clear();
    console.log('[OmniRoute] All model caches cleared');
  }
  // Also clear combo cache
  clearComboCache();
}

/**
 * Get cached models without fetching
 * @param config - OmniRoute configuration
 * @param apiKey - API key for authentication
 * @returns Cached models or null
 */
export function getCachedModels(config: OmniRouteConfig, apiKey: string): OmniRouteModel[] | null {
  const cacheKey = getCacheKey(config, apiKey);
  return modelCache.get(cacheKey)?.models || null;
}

/**
 * Check if cache is valid
 * @param config - OmniRoute configuration
 * @param apiKey - API key for authentication
 * @returns True if cache is valid
 */
export function isCacheValid(config: OmniRouteConfig, apiKey: string): boolean {
  const cacheKey = getCacheKey(config, apiKey);
  const cached = modelCache.get(cacheKey);
  if (!cached) return false;
  const ttl = config.modelCacheTtl || MODEL_CACHE_TTL;
  return Date.now() - cached.timestamp < ttl;
}

/**
 * Force refresh models from API
 * @param config - OmniRoute configuration
 * @param apiKey - API key for authentication
 * @returns Array of available models
 */
export async function refreshModels(
  config: OmniRouteConfig,
  apiKey: string,
): Promise<OmniRouteModel[]> {
  clearModelCache();
  return fetchModels(config, apiKey, true);
}

/**
 * Enrich model metadata with models.dev data and combo capabilities
 */
async function enrichModelMetadata(
  models: OmniRouteModel[],
  config: OmniRouteConfig,
): Promise<OmniRouteModel[]> {
  const modelsDevIndex = await getModelsDevIndex(config);

  // Apply models.dev metadata enrichment
  const withModelsDev =
    modelsDevIndex === null
      ? models
      : models.map((model) => applyModelsDevMetadata(model, config, modelsDevIndex));

  // Enrich combo models with lowest common capabilities
  const withComboCapabilities = await enrichComboModels(withModelsDev, config, modelsDevIndex);

  return withComboCapabilities;
}

/**
 * Apply models.dev metadata to a model
 */
function applyModelsDevMetadata(
  model: OmniRouteModel,
  config: OmniRouteConfig,
  index: ModelsDevIndex,
): OmniRouteModel {
  const { providerKey, modelKey } = splitOmniRouteModelForLookup(model.id);
  const providerAlias = resolveProviderAlias(providerKey, config);
  const lookupKey = modelKey.toLowerCase();
  const normalizedKey = normalizeModelKey(modelKey);

  // Try provider-specific exact match first
  const providerExact = providerAlias
    ? index.exactByProvider.get(providerAlias)?.get(lookupKey)
    : undefined;

  // Try provider-specific normalized match
  const providerNorm = providerAlias
    ? index.normalizedByProvider.get(providerAlias)?.get(normalizedKey)
    : undefined;

  // Try global exact match (only if single match to avoid ambiguity)
  const globalExactList = index.exactGlobal.get(lookupKey);
  const globalExact = globalExactList?.length === 1 ? globalExactList[0] : undefined;

  // Try global normalized match (only if single match to avoid ambiguity)
  const globalNormList = index.normalizedGlobal.get(normalizedKey);
  const globalNorm = globalNormList?.length === 1 ? globalNormList[0] : undefined;

  // Pick the best match (provider-specific preferred over global)
  const best = providerExact ?? providerNorm ?? globalExact ?? globalNorm;

  if (!best) return model;

  // Merge capabilities (only fill in missing values)
  return {
    ...model,
    ...(model.contextWindow === undefined && best.limit?.context !== undefined
      ? { contextWindow: best.limit.context }
      : {}),
    ...(model.maxTokens === undefined && best.limit?.output !== undefined
      ? { maxTokens: best.limit.output }
      : {}),
    ...(model.supportsVision === undefined && best.modalities?.input?.includes('image')
      ? { supportsVision: true }
      : {}),
    ...(model.supportsTools === undefined && best.tool_call === true
      ? { supportsTools: true }
      : {}),
    ...(model.supportsStreaming === undefined
      ? { supportsStreaming: true } // Assume streaming is supported by default
      : {}),
  };
}

/**
 * Split model ID for models.dev lookup
 */
function splitOmniRouteModelForLookup(
  modelId: string,
): { providerKey: string | null; modelKey: string } {
  const trimmed = modelId.trim();

  // Remove omniroute prefix if present
  const withoutPrefix = trimmed.replace(/^omniroute\//, '');

  // Split by /
  const parts = withoutPrefix.split('/').filter((p) => p.trim() !== '');

  if (parts.length >= 2) {
    return {
      providerKey: parts[0] ?? null,
      modelKey: parts.slice(1).join('/'),
    };
  }

  return { providerKey: null, modelKey: withoutPrefix };
}

/**
 * Resolve provider alias using config
 */
function resolveProviderAlias(
  providerKey: string | null,
  config: OmniRouteConfig,
): string | null {
  if (!providerKey) return null;

  const lower = providerKey.toLowerCase();

  // Default aliases
  const aliases: Record<string, string> = {
    oai: 'openai',
    openai: 'openai',
    cx: 'openai',
    codex: 'openai',
    anthropic: 'anthropic',
    claude: 'anthropic',
    gemini: 'google',
    google: 'google',
    deepseek: 'deepseek',
    mistral: 'mistral',
    xai: 'xai',
    groq: 'groq',
    together: 'together',
    openrouter: 'openrouter',
    perplexity: 'perplexity',
    cohere: 'cohere',
    ...config.modelsDev?.providerAliases,
  };

  return aliases[lower] ?? lower;
}

import type { OmniRouteConfig, OmniRouteModelMetadata } from './types.js';
import {
  MODELS_DEV_DEFAULT_URL,
  MODELS_DEV_CACHE_TTL,
  MODELS_DEV_TIMEOUT_MS,
} from './constants.js';

/**
 * models.dev model information
 */
export interface ModelsDevModel {
  id: string;
  name: string;
  family?: string;
  attachment?: boolean;
  reasoning?: boolean;
  tool_call?: boolean;
  structured_output?: boolean;
  temperature?: boolean;
  knowledge?: string;
  release_date?: string;
  last_updated?: string;
  modalities?: {
    input?: string[];
    output?: string[];
  };
  open_weights?: boolean;
  cost?: {
    input?: number;
    output?: number;
    cache_read?: number;
  };
  limit?: {
    context?: number;
    output?: number;
  };
}

/**
 * models.dev provider entry
 */
export interface ModelsDevProvider {
  id: string;
  env?: string[];
  npm?: string;
  name?: string;
  doc?: string;
  models: Record<string, ModelsDevModel>;
}

/**
 * Full models.dev API response
 */
export type ModelsDevData = Record<string, ModelsDevProvider>;

/**
 * Indexed models.dev data for efficient lookup
 */
export interface ModelsDevIndex {
  /** Provider-specific exact matches: provider -> modelId -> metadata */
  exactByProvider: Map<string, Map<string, ModelsDevModel>>;
  /** Provider-specific normalized matches: provider -> normalizedKey -> metadata */
  normalizedByProvider: Map<string, Map<string, ModelsDevModel>>;
  /** Global exact matches across all providers: modelId -> [metadata] */
  exactGlobal: Map<string, ModelsDevModel[]>;
  /** Global normalized matches: normalizedKey -> [metadata] */
  normalizedGlobal: Map<string, ModelsDevModel[]>;
}

/**
 * Cache entry for models.dev data
 */
interface ModelsDevCache {
  data: ModelsDevData;
  timestamp: number;
}

// In-memory cache for models.dev data
let modelsDevCache: ModelsDevCache | null = null;

/**
 * Fetch models.dev data with caching
 */
export async function fetchModelsDevData(
  config?: OmniRouteConfig,
): Promise<ModelsDevData | null> {
  const url = config?.modelsDev?.url ?? MODELS_DEV_DEFAULT_URL;
  const timeoutMs = config?.modelsDev?.timeoutMs ?? MODELS_DEV_TIMEOUT_MS;
  const cacheTtl = config?.modelsDev?.cacheTtl ?? MODELS_DEV_CACHE_TTL;

  // Check cache first
  if (modelsDevCache && Date.now() - modelsDevCache.timestamp < cacheTtl) {
    console.log('[OmniRoute] Using cached models.dev data');
    return modelsDevCache.data;
  }

  console.log(`[OmniRoute] Fetching models.dev data from ${url}`);

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        Accept: 'application/json',
      },
      signal: controller.signal,
    });

    if (!response.ok) {
      console.warn(`[OmniRoute] Failed to fetch models.dev data: ${response.status}`);
      return null;
    }

    const data = await response.json() as ModelsDevData;

    // Validate structure
    if (!data || typeof data !== 'object') {
      console.warn('[OmniRoute] Invalid models.dev data structure');
      return null;
    }

    // Update cache
    modelsDevCache = {
      data,
      timestamp: Date.now(),
    };

    console.log(`[OmniRoute] Successfully fetched models.dev data`);
    return data;
  } catch (error) {
    console.warn('[OmniRoute] Error fetching models.dev data:', error);
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * Build an indexed lookup structure for models.dev data
 */
export function buildModelsDevIndex(data: ModelsDevData | null): ModelsDevIndex | null {
  if (!data) return null;

  const exactByProvider = new Map<string, Map<string, ModelsDevModel>>();
  const normalizedByProvider = new Map<string, Map<string, ModelsDevModel>>();
  const exactGlobal = new Map<string, ModelsDevModel[]>();
  const normalizedGlobal = new Map<string, ModelsDevModel[]>();

  for (const [providerId, provider] of Object.entries(data)) {
    if (!provider?.models) continue;

    const providerExactMap = new Map<string, ModelsDevModel>();
    const providerNormMap = new Map<string, ModelsDevModel>();

    for (const [modelId, model] of Object.entries(provider.models)) {
      // Provider-specific lookups
      const lookupKey = modelId.toLowerCase();
      providerExactMap.set(lookupKey, model);

      const normalizedKey = normalizeModelKey(modelId);
      providerNormMap.set(normalizedKey, model);

      // Global lookups
      const globalList = exactGlobal.get(lookupKey) ?? [];
      globalList.push(model);
      exactGlobal.set(lookupKey, globalList);

      const normGlobalList = normalizedGlobal.get(normalizedKey) ?? [];
      normGlobalList.push(model);
      normalizedGlobal.set(normalizedKey, normGlobalList);
    }

    exactByProvider.set(providerId.toLowerCase(), providerExactMap);
    normalizedByProvider.set(providerId.toLowerCase(), providerNormMap);
  }

  return {
    exactByProvider,
    normalizedByProvider,
    exactGlobal,
    normalizedGlobal,
  };
}

/**
 * Get or build the models.dev index
 */
export async function getModelsDevIndex(
  config?: OmniRouteConfig,
): Promise<ModelsDevIndex | null> {
  // Check if models.dev enrichment is disabled
  if (config?.modelsDev?.enabled === false) {
    return null;
  }

  const data = await fetchModelsDevData(config);
  return buildModelsDevIndex(data);
}


/**
 * Clear the models.dev cache
 */
export function clearModelsDevCache(): void {
  modelsDevCache = null;
  console.log('[OmniRoute] models.dev cache cleared');
}

/**
 * Normalize a model key for matching
 * Removes version dates and common suffixes for fuzzy matching
 */
export function normalizeModelKey(modelId: string): string {
  return modelId
    .toLowerCase()
    // Remove date suffixes like -2024-11-20
    .replace(/-\d{4}-\d{2}-\d{2}$/, '')
    // Remove version numbers like -v1, -v2
    .replace(/-v\d+$/, '')
    // Remove common preview suffixes
    .replace(/-(preview|latest|stable)$/i, '')
    // Remove numbered versions like -4.5
    .replace(/-\d+\.\d+$/, '')
    // Normalize underscores to hyphens
    .replace(/_/g, '-');
}

/**
 * Convert models.dev model to OmniRoute metadata
 */
export function modelsDevToMetadata(model: ModelsDevModel): OmniRouteModelMetadata {
  const metadata: OmniRouteModelMetadata = {};

  if (model.name) {
    metadata.name = model.name;
  }

  if (model.limit?.context !== undefined && model.limit.context > 0) {
    metadata.contextWindow = model.limit.context;
  }

  if (model.limit?.output !== undefined && model.limit.output > 0) {
    metadata.maxTokens = model.limit.output;
  }

  // Derive vision support from modalities
  if (model.modalities?.input?.includes('image')) {
    metadata.supportsVision = true;
  }

  // Derive tool support from tool_call
  if (model.tool_call === true) {
    metadata.supportsTools = true;
  }



  // Pricing
  if (model.cost?.input !== undefined || model.cost?.output !== undefined) {
    metadata.pricing = {};
    if (model.cost.input !== undefined) {
      metadata.pricing.input = model.cost.input;
    }
    if (model.cost.output !== undefined) {
      metadata.pricing.output = model.cost.output;
    }
  }

  return metadata;
}

/**
 * Calculate lowest common capabilities from multiple models.dev entries
 * Uses MIN for numeric limits (context, maxTokens) and EVERY for booleans
 */
export function calculateLowestCommonCapabilities(
  models: ModelsDevModel[],
): OmniRouteModelMetadata {
  if (models.length === 0) {
    return {};
  }

  if (models.length === 1) {
    return modelsDevToMetadata(models[0]);
  }

  // Calculate lowest common denominator
  let minContext: number | undefined;
  let minMaxTokens: number | undefined;
  let allSupportVision = true;
  let allSupportTools = true;
  let allSupportStreaming = true;

  for (const model of models) {
    // Context window: use minimum
    const context = model.limit?.context;
    if (context !== undefined && context > 0) {
      minContext = minContext === undefined ? context : Math.min(minContext, context);
    }

    // Max tokens: use minimum
    const maxTokens = model.limit?.output;
    if (maxTokens !== undefined && maxTokens > 0) {
      minMaxTokens = minMaxTokens === undefined ? maxTokens : Math.min(minMaxTokens, maxTokens);
    }

    // Vision: all must support it
    const supportsVision = model.modalities?.input?.includes('image') ?? false;
    allSupportVision = allSupportVision && supportsVision;

    // Tools: all must support it
    const supportsTools = model.tool_call === true;
    allSupportTools = allSupportTools && supportsTools;
  }

  const result: OmniRouteModelMetadata = {};

  if (minContext !== undefined) {
    result.contextWindow = minContext;
  }

  if (minMaxTokens !== undefined) {
    result.maxTokens = minMaxTokens;
  }

  if (allSupportVision) {
    result.supportsVision = true;
  }

  if (allSupportTools) {
    result.supportsTools = true;
  }

  // Streaming is generally supported by all modern models
  if (allSupportStreaming) {
    result.supportsStreaming = true;
  }

  return result;
}


/**
 * Resolve provider alias using config and defaults
 */
export function resolveProviderAlias(
  providerKey: string | null,
  config?: OmniRouteConfig,
): string | null {
  if (!providerKey) return null;

  const lower = providerKey.toLowerCase();

  // Default aliases mapping OmniRoute provider keys to models.dev provider keys
  const aliases: Record<string, string> = {
    oai: 'openai',
    openai: 'openai',
    cx: 'openai',
    codex: 'openai',
    anthropic: 'anthropic',
    claude: 'anthropic',
    gemini: 'google',
    google: 'google',
    deepseek: 'deepseek',
    mistral: 'mistral',
    xai: 'xai',
    groq: 'groq',
    together: 'together',
    openrouter: 'openrouter',
    perplexity: 'perplexity',
    cohere: 'cohere',
    ...config?.modelsDev?.providerAliases,
  };

  return aliases[lower] ?? lower;
}

# OpenCode OmniRoute Auth Plugin

🔌 Authentication plugin for [OpenCode](https://opencode.ai) to connect to [OmniRoute](https://omniroute.ai) API.

## Features

- ✅ **Simple `/connect` Command** - No manual configuration needed
- ✅ **API Key Authentication** - Simple and secure API key-based auth
- ✅ **Dynamic Model Fetching** - Automatically fetches available models from `/v1/models` endpoint
- ✅ **Provider Auto-Registration** - Registers an `omniroute` provider via plugin hooks
- ✅ **Model Caching** - Intelligent caching with TTL for better performance
- ✅ **Fallback Models** - Default models when API is unavailable
- ✅ **Combo Model Capability Enrichment** - Automatically calculates lowest common capabilities for OmniRoute combo models

## Installation

## Quick Start

### 1. Add plugin to opencode config
```json
{
  "plugin": [
    "opencode-omniroute-auth"
  ]
}
```

### 2. Connect to OmniRoute

Simply run the `/connect` command in OpenCode:

```
/connect omniroute
```

The plugin will prompt you for your **API key**.

### 3. Done! 🎉

The plugin automatically:
- Fetches available models from `/v1/models`
- Configures OpenCode to use OmniRoute
- Stores your credentials securely

No manual configuration file editing required!

## Usage

Once connected, OpenCode will automatically use OmniRoute for AI requests:

```bash
# The plugin is now active and ready to use
# All AI requests will be routed through OmniRoute
```

### Refresh Models

By default, the plugin refreshes the model list whenever provider options are reloaded (`refreshOnList: true`).

You can disable refreshes by setting `provider.omniroute.options.refreshOnList` to `false` and clear the cache programmatically:

```typescript
import { clearModelCache } from 'opencode-omniroute-auth/runtime';

clearModelCache();
```

## Configuration (Optional)

While the plugin works out-of-the-box with `/connect`, you can also configure it manually in your OpenCode config:

```json
{
  "plugin": [
    "opencode-omniroute-auth"
  ],
  "provider": {
    "omniroute": {
      "options": {
        "baseURL": "http://localhost:20128/v1",
        "apiMode": "chat",
        "refreshOnList": true,
        "modelCacheTtl": 300000
      }
    }
  }
}
```

Use `/connect omniroute` to store your API key in `~/.local/share/opencode/auth.json`.

### Configuration Options

| Option | Type | Required | Description |
|--------|------|----------|-------------|
| `plugin` | string[] | No | npm plugin packages to load (use `opencode-omniroute-auth` when installed from npm) |
| `provider.omniroute.options.baseURL` | string | No | OmniRoute API base URL (default: `http://localhost:20128/v1`) |
| `provider.omniroute.options.apiMode` | `'chat' \| 'responses'` | No | Provider API mode (default: `chat`) |
| `provider.omniroute.options.modelCacheTtl` | number | No | Model cache TTL in milliseconds (default: 5 minutes) |
| `provider.omniroute.options.refreshOnList` | boolean | No | Whether to refresh models when provider options load (default: true) |
| `provider.omniroute.options.modelsDev` | object | No | Enrich model metadata from models.dev on refresh (default: enabled) |
| `provider.omniroute.options.modelMetadata` | object \| array | No | Override/add metadata for custom/virtual models (works well in `opencode.js`) |

### Model Metadata Enrichment (models.dev)

OmniRoute may not expose model context/output limits in `/v1/models`. When enabled, this plugin attempts to
enrich `contextWindow` and `maxTokens` by matching your OmniRoute models against `models.dev`.

You can disable enrichment or override defaults:

```js
{
  provider: {
    omniroute: {
      options: {
        modelsDev: {
          enabled: true,
          url: 'https://models.dev/api.json',
          timeoutMs: 1000,
          cacheTtl: 86400000,
          providerAliases: {
            cx: 'openai',
          },
        },
      },
    },
  },
}
```

### Custom / Virtual Model Overrides (config blocks)

For custom/virtual models (or when matching is imperfect), you can provide metadata overrides.

In `opencode.js` you can use RegExp matchers:

```js
{
  provider: {
    omniroute: {
      options: {
        modelMetadata: [
          { match: /gpt-5\.3-codex$/i, contextWindow: 200000, maxTokens: 8192 },
          { match: 'omniroute/virtual/my-custom-model', addIfMissing: true, contextWindow: 50000 },
        ],
      },
    },
  },
}
```

In JSON configs, use an object keyed by model id:

```json
{
  "provider": {
    "omniroute": {
      "options": {
        "modelMetadata": {
          "virtual/my-custom-model": { "contextWindow": 50000, "maxTokens": 2048 }
        }
      }
    }
  }
}
```

### Combo Model Capability Enrichment

OmniRoute supports "combo models" - virtual models that route to multiple underlying models with fallback strategies. This plugin automatically detects combo models and calculates their capabilities using a **lowest common denominator** approach:

- **Context Window**: Minimum of all underlying models
- **Max Tokens**: Minimum of all underlying models  
- **Vision Support**: Only if ALL underlying models support vision
- **Tool Support**: Only if ALL underlying models support tools

This ensures safe operation by never exceeding the capabilities of any single model in the combo.

**How it works:**
1. The plugin fetches combo definitions from OmniRoute's `/api/combos` endpoint
2. For each combo model, it resolves the underlying models
3. It looks up each underlying model's capabilities from `models.dev`
4. It calculates the lowest common capabilities across all resolvable models
5. These calculated capabilities are applied to the combo model

**Example:**
The "Designer" combo might route to:
- `kmc/kimi-k2.5` (context: 256000, tools: yes)
- `cx/gpt-5.1-codex-mini` (context: 204800, tools: yes)
- `gemini/models/gemini-3-flash-preview` (context: 1048576, tools: yes)

Calculated capabilities:
- Context: **204800** (minimum)
- Max Tokens: **32768** (minimum)
- Tools: **true** (all support tools)

Note: Some underlying models may not be found in `models.dev` (e.g., custom models). In such cases, they are excluded from capability calculation, and a warning is logged.

### API Mode

### API Mode

The plugin supports two provider API modes:

- `chat` (default) - best compatibility with existing OpenAI-compatible chat workflows.
- `responses` - enables Responses API mode when your OmniRoute/OpenCode setup supports it.

Example:

```json
{
  "provider": {
    "omniroute": {
      "options": {
        "apiMode": "responses"
      }
    }
  }
}
```

If an unsupported value is provided, the plugin falls back to `chat`.

## Dynamic Model Fetching

This plugin automatically fetches available models from OmniRoute's `/v1/models` endpoint. This ensures you always have access to the latest models without manual configuration.

### How It Works

1. On first request, the plugin fetches models from `/v1/models`
2. By default, models are refreshed every time you open the model list (`refreshOnList: true`)
3. If `refreshOnList` is disabled, models are cached for 5 minutes (configurable via `modelCacheTtl`)
4. If the API is unavailable, fallback models are used

## Default Models

When the `/v1/models` endpoint is unavailable, the plugin provides these fallback models:

- `gpt-4o` - GPT-4o model with full capabilities
- `gpt-4o-mini` - Fast and cost-effective
- `claude-3-5-sonnet` - Claude 3.5 Sonnet
- `llama-3-1-405b` - Llama 3.1 405B

