    token: string;
  };

  export type Auth = AuthApi | AuthOauth | AuthWellKnown;

  export type ApiAuthorizeResult =
    | {
        type: 'success';
        key: string;
        provider?: string;
      }
    | {
        type: 'failed';
      };

  export interface ApiMethod {
    type: 'api';
    label: string;
    prompts?: Prompt[];
    authorize?: (inputs?: Record<string, string>) => Promise<ApiAuthorizeResult>;
  }

  export interface OAuthMethod {
    type: 'oauth';
